using Xunit;

namespace Amenone.ArchitectureGuard.Analyzers.Tests
{
    public sealed class GeneratedCodeTests
    {
        [Fact]
        public void GeneratedFile_AutoGeneratedHeader_ShouldNotReport()
        {
            const string source = """
                // <auto-generated/>
                using UnityEngine;
                using Amenone.ArchitectureGuard;

                public sealed class GeneratedView : MonoBehaviour
                {
                #pragma warning disable AG0001
                    [AllowUnityTime("")]
                    private void Update() => Time.timeScale = Time.deltaTime;
                }
                """;

            Assert.Empty(AnalyzerRunner.AnalyzeIds(source));
        }

        [Fact]
        public void GeneratedType_GeneratedCodeAttribute_ShouldNotReport()
        {
            const string source = """
                using System.CodeDom.Compiler;
                using UnityEngine;

                [GeneratedCode("ArchitectureGuardTests", "1.0")]
                public sealed class GeneratedView : MonoBehaviour
                {
                    private void Update() => Time.timeScale = Time.deltaTime + Time.unscaledDeltaTime;
                }
                """;

            Assert.Empty(AnalyzerRunner.AnalyzeIds(source));
        }
    }
}
